import{_ as n,o as r,c as s,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const t="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-aus-vorherigem-abschnitt.png",d=JSON.parse('{"title":"Fächer aus einem früheren Lernabschnitt übernehmen","description":"","frontmatter":{"title":"Fächer aus einem früheren Lernabschnitt übernehmen","source_pageid":810,"source_revision":5357},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/faecher-aus-vorherigem-abschnitt-holen-gruppenprozesse-faecher.md","filePath":"schild3/suchen-gruppenprozesse/faecher-aus-vorherigem-abschnitt-holen-gruppenprozesse-faecher.md"}'),h={name:"schild3/suchen-gruppenprozesse/faecher-aus-vorherigem-abschnitt-holen-gruppenprozesse-faecher.md"};function a(o,e,c,p,u,l){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="facher-aus-einem-fruheren-lernabschnitt-ubernehmen" tabindex="-1">Fächer aus einem früheren Lernabschnitt übernehmen <a class="header-anchor" href="#facher-aus-einem-fruheren-lernabschnitt-ubernehmen" aria-label="Permalink to &quot;Fächer aus einem früheren Lernabschnitt übernehmen&quot;">​</a></h1><p>Holen Sie Fächer nachträglich in den aktuellen Lernabschnitt, wenn die Übernahme beim Abschnittswechsel nicht erfolgt ist. Die Optionen steuern Fächerauswahl, Mahnungen und die Prüfung vorhandener Einträge.</p><p>Mit dem Gruppenprozess <strong>Fächer aus vorherigem Abschnitt holen</strong> ist es möglich, Fächer nachträglich in den aktuellen Abschnitt zu übernehmen.</p><p>Normalerweise sollten die Fächer bei Durchführung der Versetzung beziehungsweise Übertragung in einen neuen Abschnitt ins nächste Halbjahr übertragen werden.</p><p>Sollte dies nicht gelungen sein, zum Beispiel wegen einem fehlerhaften Eintrag bei der Fortschreibungsart, kann die Übernahme mit diesem Gruppenprozess nachgeholt werden.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-faecher-aus-vorherigem-abschnitt.png"><img src="'+t+'" alt="Fächer aus einem vorherigen Abschnitt in diesen übernehmen." loading="lazy"></a></p><p><em>Fächer aus einem vorherigen Abschnitt in diesen übernehmen.</em></p><p>Wählen Sie <em>Gruppenprozesse ➜ Fächer</em> und dann <strong>Fächer aus vorherigem Abschnitt holen</strong>.</p><p>Wählen Sie den vorherigen Abschnitt, aus dem Fächer geholt werden sollen.</p><p>Mit den weiteren Häkchen wählen Sie die zu übernehmenden <strong>Fächer</strong> aus. Sie legen außerdem fest, ob gesetzte <strong>Mahnungen</strong> mit übernommen werden.</p><p>Ist im Zielabschnitt bereits Unterricht erfasst, aktivieren Sie die angebotene Prüfung vorhandener Einträge. Kontrollieren Sie nach der Übernahme, ob Fach- und Kurszuordnungen vollständig und ohne unbeabsichtigte Doppelungen vorliegen.</p><p>Starten Sie dann den <code>Prozess</code> mit dem Schalter in der Gruppenprozess-Kopfzeile.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=F%C3%A4cher_aus_vorherigem_Abschnitt_holen_(Gruppenprozesse_F%C3%A4cher)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5357.</p>',14)])])}const m=n(h,[["render",a]]);export{d as __pageData,m as default};
